import { useMemo, useState } from 'react';
import { Button, Card, Chip, Stack, Text } from '@jinx-ui/react';

type SpendStatus = 'ok' | 'warning' | 'over';

type Project = {
  id: string;
  name: string;
  quotaUsedPercent: number;
  status: SpendStatus;
};

type SpendPanelProps = {
  projects?: Project[];
};

const PAGE_SIZE = 5;

const STATUS_ORDER: SpendStatus[] = ['ok', 'warning', 'over'];

const STATUS_META: Record<SpendStatus, { label: string; color: string }> = {
  ok: { label: 'В норме', color: 'var(--jx-color-success)' },
  warning: { label: 'Близко к лимиту', color: 'var(--jx-color-warning)' },
  over: { label: 'Превышение квоты', color: 'var(--jx-color-danger)' },
};

const DEFAULT_PROJECTS: Project[] = [
  { id: 'p-01', name: 'Биллинг', quotaUsedPercent: 34, status: 'ok' },
  { id: 'p-02', name: 'Поиск по каталогу', quotaUsedPercent: 78, status: 'warning' },
  { id: 'p-03', name: 'Аналитика событий', quotaUsedPercent: 112, status: 'over' },
  { id: 'p-04', name: 'Мобильный клиент', quotaUsedPercent: 21, status: 'ok' },
  { id: 'p-05', name: 'Очереди уведомлений', quotaUsedPercent: 85, status: 'warning' },
  { id: 'p-06', name: 'Импорт данных', quotaUsedPercent: 47, status: 'ok' },
  { id: 'p-07', name: 'Рендер отчётов', quotaUsedPercent: 134, status: 'over' },
  { id: 'p-08', name: 'Медиа-хранилище', quotaUsedPercent: 62, status: 'ok' },
  { id: 'p-09', name: 'Антифрод', quotaUsedPercent: 91, status: 'warning' },
  { id: 'p-10', name: 'Служба аутентификации', quotaUsedPercent: 12, status: 'ok' },
  { id: 'p-11', name: 'Экспорт в BI', quotaUsedPercent: 103, status: 'over' },
  { id: 'p-12', name: 'Внутренние вебхуки', quotaUsedPercent: 55, status: 'ok' },
];

const RADIUS = 18;
const CIRCUMFERENCE = 2 * Math.PI * RADIUS;

export default function ProjectSpendPanel({ projects = DEFAULT_PROJECTS }: SpendPanelProps) {
  const [activeStatuses, setActiveStatuses] = useState<SpendStatus[]>(STATUS_ORDER);
  const [page, setPage] = useState(0);

  const visibleProjects = useMemo(
    () => projects.filter((project) => activeStatuses.includes(project.status)),
    [projects, activeStatuses],
  );

  const totalPages = Math.max(1, Math.ceil(visibleProjects.length / PAGE_SIZE));
  const currentPage = Math.min(page, totalPages - 1);
  const pageProjects = visibleProjects.slice(currentPage * PAGE_SIZE, currentPage * PAGE_SIZE + PAGE_SIZE);

  const toggleStatus = (status: SpendStatus) => {
    setPage(0);
    setActiveStatuses((current) =>
      current.includes(status) ? current.filter((item) => item !== status) : [...current, status],
    );
  };

  const resetFilters = () => {
    setPage(0);
    setActiveStatuses(STATUS_ORDER);
  };

  return (
    <Card className="jx-card jx-p-4">
      <Stack direction="vertical" gap="lg">
        <Stack direction="horizontal" gap="sm" wrap>
          {STATUS_ORDER.map((status) => {
            const isActive = activeStatuses.includes(status);
            return (
              <Chip
                key={status}
                selected={isActive}
                aria-pressed={isActive}
                onClick={() => toggleStatus(status)}
              >
                {STATUS_META[status].label}
              </Chip>
            );
          })}
        </Stack>

        {pageProjects.length === 0 ? (
          <Stack direction="vertical" gap="md" align="center" className="jx-py-6">
            <Text variant="body" tone="muted">
              Нет проектов, подходящих под выбранные фильтры.
            </Text>
            <Button variant="primary" onClick={resetFilters}>
              Сбросить фильтры
            </Button>
          </Stack>
        ) : (
          <Stack direction="vertical" gap="sm">
            {pageProjects.map((project) => {
              const percent = Math.max(0, Math.min(100, project.quotaUsedPercent));
              const meta = STATUS_META[project.status];
              return (
                <Stack
                  key={project.id}
                  direction="horizontal"
                  align="center"
                  justify="space-between"
                  gap="md"
                  className="jx-p-3 jx-rounded jx-border"
                >
                  <Text variant="body" weight="medium">
                    {project.name}
                  </Text>

                  <Stack direction="horizontal" align="center" gap="md">
                    <svg
                      width={44}
                      height={44}
                      viewBox="0 0 44 44"
                      role="img"
                      aria-label={`Квота использована на ${project.quotaUsedPercent}%`}
                    >
                      <circle
                        cx={22}
                        cy={22}
                        r={RADIUS}
                        fill="none"
                        stroke="var(--jx-color-border)"
                        strokeWidth={4}
                      />
                      <circle
                        cx={22}
                        cy={22}
                        r={RADIUS}
                        fill="none"
                        stroke={meta.color}
                        strokeWidth={4}
                        strokeLinecap="round"
                        strokeDasharray={CIRCUMFERENCE}
                        strokeDashoffset={CIRCUMFERENCE * (1 - percent / 100)}
                        transform="rotate(-90 22 22)"
                      />
                      <text
                        x={22}
                        y={22}
                        textAnchor="middle"
                        dominantBaseline="central"
                        fill="var(--jx-color-text)"
                        fontSize="var(--jx-font-size-xs)"
                      >
                        {project.quotaUsedPercent}%
                      </text>
                    </svg>

                    <Text variant="caption" style={{ color: meta.color }}>
                      {meta.label}
                    </Text>
                  </Stack>
                </Stack>
              );
            })}
          </Stack>
        )}

        {visibleProjects.length > 0 && (
          <Stack direction="horizontal" align="center" justify="space-between" gap="md">
            <Text variant="caption" tone="muted">
              Страница {currentPage + 1} из {totalPages}
            </Text>
            <Stack direction="horizontal" gap="sm">
              <Button
                variant="secondary"
                disabled={currentPage === 0}
                onClick={() => setPage(currentPage - 1)}
              >
                Назад
              </Button>
              <Button
                variant="secondary"
                disabled={currentPage >= totalPages - 1}
                onClick={() => setPage(currentPage + 1)}
              >
                Вперёд
              </Button>
            </Stack>
          </Stack>
        )}
      </Stack>
    </Card>
  );
}

